@Test public void testGoodAuthentication() throws Exception {
  runInContext(() -> {
    try {
      boolean authSequenceCompleted=authenticate(AUTH_KEY_ID1,AUTH_PRIVATE_KEY1);
      Assert.assertTrue(authSequenceCompleted);
      Assert.assertFalse(disconnected);
      recvBuffer="weather,location=us-midwest temperature=82 1465839830100400200\n";
      handleContextIO();
      Assert.assertFalse(disconnected);
      waitForIOCompletion();
      closeContext();
      String expected="location\ttemperature\ttimestamp\n" + "us-midwest\t82.0\t2016-06-13T17:43:50.100400Z\n";
      assertTable(expected);
    } catch (SignatureException | IllegalArgumentException | RuntimeException e) {
      Assert.fail("Unexpected exception: " + e.getMessage());
    }
  });
}
